consulta:
cat > /home/learner/aso/f22/consulta.sh <<'SOLUCION'
#!/bin/bash
read -r usuario campo
[ -n "$usuario" ] && [ -n "$campo" ] || { echo 'error: escribe USUARIO CAMPO' >&2; exit 1; }
linea=$(getent passwd "$usuario") || { echo "error: $usuario no existe" >&2; exit 2; }
IFS=: read -r login x uid gid gecos home shell <<< "$linea"
case $campo in
    uid) echo "$uid" ;;
    home) echo "$home" ;;
    shell) echo "$shell" ;;
    *) echo 'error: campo no válido' >&2; exit 3 ;;
esac
SOLUCION
chmod 755 /home/learner/aso/f22/consulta.sh
chown learner:learner /home/learner/aso/f22/consulta.sh

servicio:
cat > /home/learner/aso/f22/servicio.sh <<'SOLUCION'
#!/bin/bash
[ $# -eq 1 ] || { echo 'uso: servicio.sh PUERTO/PROTOCOLO' >&2; exit 1; }
patron='^([0-9]+)/(tcp|udp)$'
[[ $1 =~ $patron ]] || { echo 'error: formato PUERTO/tcp o PUERTO/udp' >&2; exit 2; }
puerto=${BASH_REMATCH[1]} proto=${BASH_REMATCH[2]}
nombres=()
while read -r nombre pp resto; do
    [ "$pp" = "$puerto/$proto" ] && nombres+=("$nombre")
done < /etc/services
(( ${#nombres[@]} > 0 )) || { echo "error: ningún servicio en $1" >&2; exit 3; }
echo "Puerto $puerto ($proto): ${nombres[*]}"
SOLUCION
chmod 755 /home/learner/aso/f22/servicio.sh
chown learner:learner /home/learner/aso/f22/servicio.sh

clasifica:
cat > /home/learner/aso/f22/clasifica.sh <<'SOLUCION'
#!/bin/bash
shopt -s extglob
[ $# -ge 1 ] || { echo 'uso: clasifica.sh RUTA...' >&2; exit 1; }
for r in "$@"; do
    n=${r##*/}
    case $n in
        @(*.conf|*.cfg)) t=configuración ;;
        *.@(gz|xz|bz2|zip)) t=comprimido ;;
        lib*.so*(.+([0-9]))) t=biblioteca ;;
        +([0-9])) t=número ;;
        *) t=otro ;;
    esac
    echo "$r: $t"
done
SOLUCION
chmod 755 /home/learner/aso/f22/clasifica.sh
chown learner:learner /home/learner/aso/f22/clasifica.sh

ruta:
cat > /home/learner/aso/f22/ruta.sh <<'SOLUCION'
#!/bin/bash
[ $# -eq 1 ] || { echo 'uso: ruta.sh RUTA' >&2; exit 1; }
r=$1
[ "${r#/}" != "$r" ] || { echo "error: $r debe ser absoluta" >&2; exit 2; }
nombre=${r##*/}
echo "Directorio: ${r%/*}"
echo "Nombre: $nombre"
if [[ $nombre == *.* ]]; then echo "Extensión: ${nombre##*.}"; else echo 'Extensión: (ninguna)'; fi
echo "Base: ${nombre%%.*}"
SOLUCION
chmod 755 /home/learner/aso/f22/ruta.sh
chown learner:learner /home/learner/aso/f22/ruta.sh
